use vstd::prelude::*;

verus! {

fn flipud(m: Vec<f32>) -> (result: Vec<f32>)
    ensures
        result.len() == m.len(),
        forall|i: int|
            0 <= i < result.len() ==> result[i] == m[(m.len() - 1 - i) as int],
{
    let n: usize = m.len();
    let mut result: Vec<f32> = Vec::new();

    let mut i: usize = 0;
    while i < n
        invariant
            result.len() == i,
            i <= n,
            forall|k: int|
                0 <= k < i ==> result[k] == m[(n - 1 - k) as int],
        decreases n - i,
    {
        // Since i < n, n - 1 - i is a valid index into m.
        let j: usize = n - 1 - i;
        result.push(m[j]);
        i += 1;
    }

    result
}

} // verus!

